\begin{lemma}

source_context:
\label{lemma-restrict-lower-shriek}
Let $S$ be a scheme. Let $j : U \to X$ be a \'etale morphism of algebraic
spaces over $S$. Given an \'etale morphism $V \to Y$, set $W = V \times_X U$
and denote $j_W : W \to V$ the projection morphism. Then
$(j_!E)|_V = j_{W!}(E|_W)$ for $E$ in $D(\mathcal{O}_U)$.
\end{lemma}

\begin{proof}
This is true because
$(j_!\mathcal{F})|_V = j_{W!}(\mathcal{F}|_W)$
for an $\mathcal{O}_X$-module $\mathcal{F}$ as follows immediately 
from the construction of the functors $j_!$ and $j_{W!}$, see
Modules on Sites, Lemma \ref{sites-modules-lemma-extension-by-zero}.
\end{proof}

\begin{lemma}

public_context:
\label{lemma-restrict-lower-shriek}
Soit $S$ un sch\'ema. Soit $j : U \to X$ un morphisme \'etale d'espaces
alg\'ebriques sur $S$. Pour tout morphisme \'etale $V \to X$, posons
$W = V \times_X U$ et notons $j_W : W \to V$ le morphisme de projection.
Alors $(j_!E)|_V = j_{W!}(E|_W)$ pour tout $E$ de $D(\mathcal{O}_U)$.
\end{lemma}

\begin{proof}
Cela r\'esulte de l'\'egalit\'e
$(j_!\mathcal{F})|_V = j_{W!}(\mathcal{F}|_W)$ pour tout
$\mathcal{O}_X$-module $\mathcal{F}$, laquelle d\'ecoule imm\'ediatement de la
construction des foncteurs $j_!$ et $j_{W!}$; voir Modules sur les sites,
lemme \ref{sites-modules-lemma-extension-by-zero}.
\end{proof}

\begin{lemma}

source_context:
\label{lemma-locally-closed-where-H0-locally-free}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subspace $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$ if and only if
for all morphisms $g : Y' \to Y$ the $\mathcal{O}_{Y'}$-module
$H^a(L(f \circ g)^*E)$ is locally free of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in |X|$, then $j$ is
a closed immersion and given $f : Y \to X$ the following are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^0(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^0(Lf^*E), H^0(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}
\end{lemma}

\begin{proof}
Omitted. Hints:
Follows from the case of schemes by \'etale localization. See
Derived Categories of Schemes, Lemma
\ref{perfect-lemma-locally-closed-where-H0-locally-free}.
\end{proof}

\begin{lemma}

public_context:
\label{lemma-locally-closed-where-H0-locally-free}
Soit $S$ un sch\'ema. Soit $X$ un espace alg\'ebrique sur $S$.
Soit $E\in D(\mathcal{O}_X)$ parfait, de Tor-amplitude contenue dans
$[a,b]$ pour certains $a,b\in\mathbf{Z}$.
Soit $r\geq0$.
Il existe alors un sous-espace localement ferm\'e $j:Z\to X$ caract\'eris\'e
par les propri\'et\'es suivantes :
\begin{enumerate}
\item $H^a(Lj^*E)$ est un $\mathcal{O}_Z$-module localement libre de rang $r$ ;
\item un morphisme $f:Y\to X$ se factorise par $Z$ si et seulement si, pour
tout morphisme $g:Y'\to Y$, le $\mathcal{O}_{Y'}$-module
$H^a(L(f\circ g)^*E)$ est localement libre de rang $r$.
\end{enumerate}
De plus, $j:Z\to X$ est de pr\'esentation finie et
\begin{enumerate}
\item[(3)] si $f:Y\to X$ se factorise sous la forme
$Y\xrightarrow{g}Z\to X$, alors
$H^a(Lf^*E)=g^*H^a(Lj^*E)$ ;
\item[(4)] si $\beta_a(x)\leq r$ pour tout $x\in|X|$, alors $j$ est une
immersion ferm\'ee et, pour tout $f:Y\to X$, les conditions suivantes sont
\'equivalentes :
\begin{enumerate}
\item $f:Y\to X$ se factorise par $Z$ ;
\item $H^a(Lf^*E)$ est un $\mathcal{O}_Y$-module localement libre de rang $r$ ;
\end{enumerate}
et, si $r=1$, elles sont encore \'equivalentes \`a
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y\to
\SheafHom_{\mathcal{O}_Y}(H^a(Lf^*E),H^a(Lf^*E))$ est injectif.
\end{enumerate}
\end{enumerate}
\end{lemma}

\begin{proof}
D\'emonstration omise. Indications :
on se ram\`ene au cas des sch\'emas par localisation \'etale. Voir Cat\'egories
d\'eriv\'ees des sch\'emas, lemme
\ref{perfect-lemma-locally-closed-where-H0-locally-free}.
\end{proof}

